  "inlineSchema": "// iPhone 18 Pro Max Stock Bot - Apple Store Thailand\n// Availability source: GET https://www.apple.com/th/shop/retail/pickup-message\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// Observed availability. UNKNOWN is used whenever Apple could not be reached\n/// or returned a shape we do not understand. UNKNOWN is NEVER treated as\n/// UNAVAILABLE - that would produce false \"back in stock\" alerts.\nenum StockStatus {\n  AVAILABLE\n  UNAVAILABLE\n  UNKNOWN\n}\n\nmodel Product {\n  id        String           @id @default(uuid())\n  model     String           @unique /// e.g. \"iPhone 18 Pro Max\"\n  createdAt DateTime         @default(now())\n  updatedAt DateTime         @updatedAt\n  variants  ProductVariant[]\n\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id         String   @id @default(uuid())\n  productId  String   @map(\"product_id\")\n  /// Apple part number, e.g. \"MJXQ4ZP/A\" - the true variant identifier\n  partNumber String   @unique @map(\"part_number\")\n  /// Apple base part number, e.g. \"MJXQ4\"\n  basePart   String?  @map(\"base_part\")\n  color      String /// canonical English name, e.g. \"Burgundy\"\n  colorTh    String?  @map(\"color_th\") /// Thai display name, e.g. \"เบอร์กันดี\"\n  storage    String /// e.g. \"256GB\"\n  priceTHB   Decimal? @map(\"price_thb\") @db.Decimal(12, 2)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  stocks  Stock[]\n\n  @@unique([productId, color, storage])\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\nmodel Store {\n  id        String  @id @default(uuid())\n  /// Apple store number, e.g. \"R733\" (Central World), \"R728\" (Iconsiam)\n  code      String  @unique\n  name      String /// e.g. \"Apple Central World\"\n  rawName   String? @map(\"raw_name\") /// exactly as Apple returns it\n  city      String?\n  province  String?\n  address   String?\n  country   String  @default(\"TH\")\n  latitude  Float?\n  longitude Float?\n  storeUrl  String? @map(\"store_url\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  stocks Stock[]\n\n  @@map(\"stores\")\n}\n\nmodel Stock {\n  id        String @id @default(uuid())\n  variantId String @map(\"variant_id\")\n  storeId   String @map(\"store_id\")\n\n  /// Last DEFINITIVE answer from Apple. Not touched by UNKNOWN checks,\n  /// which is what makes the bot restart- and outage-safe.\n  available Boolean     @default(false)\n  /// Last OBSERVED status, including UNKNOWN.\n  status    StockStatus @default(UNKNOWN)\n\n  lastCheckedAt   DateTime? @map(\"last_checked_at\")\n  lastAvailableAt DateTime? @map(\"last_available_at\")\n  /// Set on the very first observation so first-run never notifies.\n  firstSeenAt     DateTime  @default(now()) @map(\"first_seen_at\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  variant          ProductVariant    @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  history          StockHistory[]\n  notificationLogs NotificationLog[]\n\n  @@unique([variantId, storeId])\n  @@index([available])\n  @@index([storeId])\n  @@map(\"stocks\")\n}\n\n/// One row per OBSERVED CHANGE (not one row per check) to keep the table small.\nmodel StockHistory {\n  id        String      @id @default(uuid())\n  stockId   String      @map(\"stock_id\")\n  available Boolean?\n  status    StockStatus\n  checkedAt DateTime    @default(now()) @map(\"checked_at\")\n\n  stock Stock @relation(fields: [stockId], references: [id], onDelete: Cascade)\n\n  @@index([stockId, checkedAt])\n  @@map(\"stock_history\")\n}\n\nmodel NotificationLog {\n  id             String      @id @default(uuid())\n  stockId        String      @map(\"stock_id\")\n  previousStatus StockStatus @map(\"previous_status\")\n  currentStatus  StockStatus @map(\"current_status\")\n  sentAt         DateTime    @default(now()) @map(\"sent_at\")\n  messageId      String?     @map(\"message_id\")\n  success        Boolean     @default(true)\n  error          String?\n\n  stock Stock @relation(fields: [stockId], references: [id], onDelete: Cascade)\n\n  @@index([stockId, sentAt])\n  @@map(\"notification_logs\")\n}\n\n/// Cooperative lock so multiple bot instances never run a check concurrently.\nmodel JobLock {\n  name      String   @id\n  owner     String\n  lockedAt  DateTime @default(now()) @map(\"locked_at\")\n  expiresAt DateTime @map(\"expires_at\")\n\n  @@map(\"job_locks\")\n}\n",
